package com.xdownload.mobile;
import android.content.Context;import android.graphics.*;import android.view.View;import java.util.Arrays;
/** Sixteen proportional windows into actual byte coverage, not an estimate from total progress. */
final class RangeStrip extends View{private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final int accent,muted;private int[] coverage=new int[16];RangeStrip(Context c,int a,int m){super(c);accent=a;muted=m;}void update(int[] next){if(next.length==16&&!Arrays.equals(next,coverage)){coverage=next.clone();invalidate();}}@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float cell=getWidth()/16f,gap=Math.max(1,getResources().getDisplayMetrics().density*2),top=getHeight()*0.2f,bottom=getHeight()*0.8f;for(int i=0;i<16;i++){float left=cell*i,right=Math.max(left,cell*(i+1)-gap);paint.setColor(muted);paint.setAlpha(70);canvas.drawRect(left,top,right,bottom,paint);paint.setColor(accent);paint.setAlpha(255);canvas.drawRect(left,top,left+(right-left)*coverage[i]/1000f,bottom,paint);}}}